    public static function get(string $name, int $size = 18, string $class = '', float $strokeWidth = 2): string {
        $content = self::$icons[$name] ?? '';
        if (empty($content)) {
            return '';
        }
        $classAttr = ' class="sgm-icon' . ($class ? ' ' . htmlspecialchars($class) : '') . '"';
        return '<svg xmlns="http://www.w3.org/2000/svg" width="' . $size . '" height="' . $size . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="' . $strokeWidth . '" stroke-linecap="round" stroke-linejoin="round"' . $classAttr . ' style="vertical-align: middle; display: inline-block;">' . $content . '</svg>';
    }
